import app.nesquikos.playlist.*;import org.json.*;import java.util.*;import java.nio.file.*;
public class IndexTest {
 static int checks;
 static void ok(boolean x,String why){checks++;if(!x)throw new AssertionError(why);}
 static JSONObject text(String t)throws Exception{return new JSONObject().put("simpleText",t);}
 static JSONObject video(int id,String title,String channel)throws Exception{return new JSONObject().put("playlistVideoRenderer",new JSONObject().put("videoId",String.format("%011d",id)).put("title",text(title)).put("shortBylineText",text(channel)));}
 static JSONObject list(JSONArray a,String token)throws Exception{JSONObject l=new JSONObject().put("playlistId","WL").put("contents",a);if(!token.isEmpty())l.put("continuations",new JSONArray().put(new JSONObject().put("nextContinuationData",new JSONObject().put("continuation",token))));return l;}
 static JSONObject initial(JSONObject l)throws Exception{JSONArray contents=new JSONArray().put(new JSONObject().put("playlistVideoListRenderer",l)).put(new JSONObject().put("videoRenderer",new JSONObject().put("title",text("Polo outside"))));return new JSONObject().put("contents",new JSONObject().put("sectionListRenderer",new JSONObject().put("contents",contents)));}
 static void reject(JSONObject r,boolean c,String target)throws Exception{try{PlaylistIndex.parse(r,"WL",c,target);throw new AssertionError("Unexpected acceptance");}catch(JSONException expected){checks++;}}
 public static void main(String[] args)throws Exception{
  JSONArray a=new JSONArray().put(video(1,"Polo titre","Autre chaîne")).put(video(2,"Différent","Polo")).put(video(3,"Polo","Polo")).put(video(4,"Autre","Autre"));
  PlaylistIndex.Page p=PlaylistIndex.parse(initial(list(a,"next")),"WL",false,"");
  ok(p.videos.size()==4,"Membership");ok(PlaylistIndex.filter(p.videos,"POLO").size()==3,"Title or channel, one result each");ok(PlaylistIndex.filter(p.videos,"autre chaine").size()==1,"Accents");ok(PlaylistIndex.normalize("PÔLE").equals("pole"),"Unicode");ok(PlaylistIndex.filter(p.videos,"").size()==4,"Empty query");ok(PlaylistIndex.filter(p.videos,"absent").isEmpty(),"Zero matches");ok(p.next.equals("next"),"Continuation token");
  LinkedHashMap<String,PlaylistIndex.Video> index=new LinkedHashMap<String,PlaylistIndex.Video>();
  for(int start=0;start<1100;start+=100){JSONArray rows=new JSONArray();for(int j=start;j<start+100;j++)rows.put(video(j,j==299||j==999?"Polo":"X",j==1000?"Polo":"Y"));JSONObject l=list(rows,start==1000?"":"next"+start);JSONObject r=start==0?initial(l):new JSONObject().put("continuationContents",new JSONObject().put("playlistVideoListContinuation",l));p=PlaylistIndex.parse(r,"WL",start!=0,"");for(PlaylistIndex.Video v:p.videos)if(!index.containsKey(v.id))index.put(v.id,v);}
  ok(index.size()==1100,"1100 videos");ok(p.next.isEmpty(),"End");List<PlaylistIndex.Video> filtered=PlaylistIndex.filter(index.values(),"polo");ok(filtered.size()==3,"Positions 300/1000/1001");ok(filtered.get(1).id.equals("00000000999"),"Order");
  reject(initial(list(a,"").put("playlistId","OTHER")),false,"");reject(new JSONObject(),false,"");reject(new JSONObject().put("error",new JSONObject()),false,"");reject(initial(list(new JSONArray().put(new JSONObject().put("videoRenderer",new JSONObject())),"")),false,"");
  JSONObject append=new JSONObject().put("appendContinuationItemsAction",new JSONObject().put("targetId","playlist-list").put("continuationItems",new JSONArray().put(video(88,"Polo","A"))));JSONObject r=new JSONObject().put("onResponseReceivedActions",new JSONArray().put(append));ok(PlaylistIndex.parse(r,"WL",true,"playlist-list").videos.size()==1,"Append");reject(r,true,"other-target");
  Map<String,String> h=new HashMap<String,String>();h.put("Authorization","TEST_A");PlaylistSession.capture("https://youtubei.googleapis.com/youtubei/v1/browse",h);PlaylistSession.Snapshot s=PlaylistSession.snapshot();PlaylistSession.capture("https://example.org/youtubei/v1/browse",Collections.singletonMap("Authorization","TEST_B"));ok(PlaylistSession.valid(s),"Fixed host");h.put("Authorization","TEST_B");PlaylistSession.capture("https://youtubei.googleapis.com/youtubei/v1/browse",h);ok(!PlaylistSession.valid(s),"Account isolation");s=PlaylistSession.snapshot();PlaylistSession.incognito(true);ok(!PlaylistSession.valid(s)&&!PlaylistSession.snapshot().headers.containsKey("Authorization"),"Incognito");
  System.out.println("PASS "+checks+" synthetic assertions");
  if(args.length>0){JSONObject live=new JSONObject(new String(Files.readAllBytes(Paths.get(args[0])),"UTF-8"));p=PlaylistIndex.parse(live,"PLzH6n4zXuckpfMu_4Ff8E7Z1behQks5ba",false,"");ok(p.videos.size()==11,"11 live public videos");ok(PlaylistIndex.filter(p.videos,"Computerphile").size()==11,"Live channel search");System.out.println("PASS live public response: "+p.videos.size()+" videos; channel matches=11; next="+!p.next.isEmpty());}
 }
}
